## Requirements

- Portable C99. Include `<math.h>`, `"gdn_layer.h"`, `"gdn.h"`, `"ops.h"`. No allocation, no globals.
- Carve every temporary out of `scratch`, in this order: qkv [conv_dim], c [conv_dim], z [Hv*Dv], y [Hv*Dv], a [Hv], b [Hv], g [Hv], beta [Hv].
  That is exactly GDN_SCRATCH_FLOATS. Use `c` for the conv output and normalise q and k inside `c` in place.
- Step 7 needs a temporary for the normed head: write op_rmsnorm's result into the qkv buffer (no longer needed
  by then), then op_silu_mul(y_h, z_h, normed, Dv) writes the gated result back into y_h.
- Check the return value of every qmat_matvec call; return -1 on failure.
- Under 50 lines per function; a static helper for the projections is fine.

Return only the complete `gdn_layer.c` in one fenced code block.

```c
#include "gdn_layer.h"
#include "gdn.h"
#include "ops.h"
#include <math.h>

int gdn_layer_step(float *out, const float *x, const GdnWeights *w, GdnState *st, float *scratch) {
    int KD = w->Hk * w->Dk;
    int VD = w->Hv * w->Dv;
    int conv_dim = 2 * KD + VD;

    /* Scratch layout per brief:
     * qkv [conv_dim], c [conv_dim], z [VD], y [VD], a [Hv], b [Hv], g [Hv], beta [Hv]
     */
    float *qkv = scratch;
    float *c = qkv + conv_dim;
    float *z = c + conv_dim;
    float *y = z + VD;
    float *a = y + VD;
    float *b = a + w->Hv;
    float *g = b + w->Hv;
    float *beta = g + w->Hv;

    /* Step 1: projections into their own buffers */
    if (qmat_matvec(&w->qkv, x, qkv) != 0) return -1;
    if (qmat_matvec(&w->z, x, z) != 0) return -1;
    if (qmat_matvec(&w->a, x, a) != 0) return -1;
    if (qmat_matvec(&w->b, x, b) != 0) return -1;

    /* Step 2: convolution */
    gdn_conv_step(c, st->conv_state, qkv, w->conv_w, conv_dim, w->K);

    /* Step 3: split c into q, k, v */
    /* q = c, k = c + KD, v = c + 2*KD */

    /* Step 4: L2 normalize q and k heads */
    for (int h = 0; h < w->Hk; h++) {
        gdn_l2norm(c + h * w->Dk, w->Dk, 1e-6, 1.0f / sqrtf((float)w->Dk));
        gdn_l2norm(c + KD + h * w->Dk, w->Dk, 1e-6, 1.0f);
    }

    /* Step 5: gates */
    gdn_gates(g, beta, a, b, w->A_log, w->dt_bias, w->Hv);

    /* Step 6: recurrent step */
    gdn_recurrent_step(y, st->rec_state, c, c + KD, c + 2 * KD, g, beta, w->Hk, w->Hv, w->Dk, w->Dv);

    /* Step 7: gated RMSNorm + SiLU */
    /* Use qkv buffer as temporary for normed output (no longer needed) */
    for (int h = 0; h < w->Hv; h++) {
        float *normed = qkv;
        float *z_h = z + h * w->Dv;
        float *y_h = y + h * w->Dv;
        op_rmsnorm(normed, y_h, w->norm_w, w->Dv, w->eps);
        op_silu_mul(y_h, z_h, normed, w->Dv);
    }

    /* Step 8: output projection */
    return qmat_matvec(&w->out, y, out);
}
```

# Task: implement engine/src/attn_layer.c

Write `engine/src/attn_layer.c`, implementing `attn_layer_step` from this header. The numbered steps and the scratch layout in the comments are the spec: follow them exactly.

```c
/* attn_layer.h: one full-attention layer of Qwen3.5 (gated GQA + partial RoPE), one token at a time.
 * Input is the hidden state AFTER input_layernorm; output is the attention branch BEFORE the residual add.
 * Matches mlx_lm.models.qwen3_next.Qwen3NextAttention with a causal mask.
 */
#ifndef ATTN_LAYER_H
#define ATTN_LAYER_H
#include "qmat.h"

typedef struct {
    QMat q;               /* hidden -> Hq * 2D. Per head h the 2D outputs are [query(D) | gate(D)]  */
    QMat k;               /* hidden -> Hkv * D */
    QMat v;               /* hidden -> Hkv * D */
    QMat o;               /* Hq * D -> hidden  */
    const float *q_norm;  /* [D] RMSNorm weight applied to every query head */
    const float *k_norm;  /* [D] RMSNorm weight applied to every key head   */
    int hidden, Hq, Hkv, D, rot_dims;
    float rope_theta, eps;
} AttnWeights;

typedef struct {
    float *k_cache;       /* [max_len][Hkv * D] keys AFTER k_norm and RoPE */
    float *v_cache;       /* [max_len][Hkv * D] */
    int len;              /* tokens cached so far = position of the next token */
    int max_len;
} AttnCache;

#define ATTN_SCRATCH_FLOATS(w, max_len) (2 * (w)->Hq * (w)->D + (w)->Hq * (w)->D + 2 * (w)->Hkv * (w)->D + (max_len))

/* out[hidden] = layer(x[hidden]) for the token at position pos = cache->len; then cache->len++.
 * scratch holds ATTN_SCRATCH_FLOATS(w, cache->max_len) floats. Steps:
 *   1. qg = qmat(w->q, x)   [Hq * 2D];  kx = qmat(w->k, x) [Hkv*D];  vx = qmat(w->v, x) [Hkv*D]
 *   2. split qg per head h: query_h = qg[h*2D .. h*2D + D),  gate_h = qg[h*2D + D .. h*2D + 2D)
 *      Copy the queries into a contiguous q [Hq*D] buffer and the gates into gate [Hq*D].
 *   3. op_rmsnorm each query head with w->q_norm and each key head with w->k_norm (eps = w->eps), in place
 *      is NOT allowed by op_rmsnorm (no aliasing), so normalise into the destination buffer.
 *   4. op_rope(q, Hq, D, rot_dims, pos, rope_theta) and op_rope(k, Hkv, D, rot_dims, pos, rope_theta)
 *   5. store k and vx at row pos of k_cache / v_cache
 *   6. for each query head h, kv head kvh = h / (Hq / Hkv):
 *        s[t] = dot(q_h, k_cache[t][kvh]) / sqrt(D)     for t in [0, pos]
 *        p = op_softmax(s)
 *        att_h[i] = sum_t p[t] * v_cache[t][kvh*D + i]
 *   7. att[j] *= sigmoid(gate[j])  for all j < Hq*D
 *   8. out = qmat(w->o, att)
 * Returns 0; -1 if the cache is full or a qmat_matvec call fails. */
int attn_layer_step(float *out, const float *x, const AttnWeights *w, AttnCache *cache, float *scratch);

#endif
```

