    float *qg = scratch;
    float *q = qg + 2 * QD;
    float *att = q + QD;
    float *kx = att + QD;
    float *k = kx + KD;
    float *vx = k + KD;
    float *s = vx + KD;

    /* Step 1: project */
    if (qmat_matvec(&w->q, x, qg) != 0) return -1;
    if (qmat_matvec(&w->k, x, kx) != 0) return -1;
    if (qmat_matvec(&w->v, x, vx) != 0) return -1;

