        for (int t = 0; t <= pos; t++) {
            float score = 0.0f;
            const float *k_t = cache->k_cache + t * KD + kvh * D;
            for (int i = 0; i < D; i++) score += q_h[i] * k_t[i];
            score /= sqrtf((float)D);
            s[t] = score;
