        text[i+1]<'0' || text[i+1]>'9' || text[i+2]!='\0') return -1;
    unsigned sec=(unsigned)(text[i]-'0')*10u+(unsigned)(text[i+1]-'0');
    if (sec>59u || minutes>(UINT_MAX-sec)/60u) return -1;
    *seconds=minutes*60u+sec;
    return 0;
}
